import pandas as pd

def find_customers(orders: pd.DataFrame) -> pd.DataFrame:
    if orders.empty:
        return pd.DataFrame({'customer_id': []})
    orders = orders.copy()
    orders['year'] = pd.to_datetime(orders['order_date']).dt.year
    yearly = orders.groupby(['customer_id', 'year'])['price'].sum().reset_index()
    valid_customers = []
    for cust_id, group in yearly.groupby('customer_id'):
        group = group.sort_values('year')
        years = group['year'].tolist()
        prices = group['price'].tolist()
        has_gap = any(years[i + 1] - years[i] != 1 for i in range(len(years) - 1))
        is_increasing = all(prices[i + 1] > prices[i] for i in range(len(prices) - 1))
        if not has_gap and is_increasing:
            valid_customers.append(cust_id)
    return pd.DataFrame({'customer_id': valid_customers})
